# -*- coding: utf-8 -*-
"""Begriffe zum Designrecht (DesignG, DesignV, GGV, DesignRL). Felder wie knowledge/concepts.py;
`norms` in der Zitierweise `§ 2 Abs. 3 DesignG`, `§ 7 DesignV`, `Art. 6 GGV`, `Art. 5 DesignRL`, `Art. 19 DesignRL 2024`; `ipwiki` bleibt leer."""


def c(id, label, kategorie, definition, erlaeuterung, norms=(), cases=(), related=()):
    return dict(id=id, label=label, kategorie=kategorie, definition=definition, erlaeuterung=erlaeuterung,
                norms=list(norms), cases=list(cases), ipwiki=[], related=list(related), quellen=[])


S, A, V, N, W, R, U, E = ("Design: Schutzvoraussetzungen", "Design: Anmeldung und Eintragung (DPMA)", "Design: Berechtigte und Rechtsverkehr",
                          "Design: Nichtigkeit", "Design: Schutzwirkung und Schranken", "Design: Rechtsfolgen und Verfahren",
                          "Design: Unionsgeschmacksmuster und internationales Design", "Design: Europäischer Rahmen und Abgrenzung")

CONCEPTS = [
    # ------------------------------------------------------------------ Schutzvoraussetzungen
    c("des_design_begriff", "Design (§ 1 Nr. 1 DesignG)", S,
      "Ein Design ist die zwei- oder dreidimensionale Erscheinungsform eines ganzen Erzeugnisses oder eines Teils davon, die sich insbesondere aus den Merkmalen der Linien, Konturen, Farben, der Gestalt, Oberflächenstruktur oder der Werkstoffe des Erzeugnisses selbst oder seiner Verzierung ergibt (§ 1 Nr. 1 DesignG, Art. 1 lit. a DesignRL, Art. 3 Nr. 1 GGV).",
      "Geschützt wird die sichtbare Erscheinungsform, nicht die Idee, die Funktion oder das Konzept. Auch Teile eines Erzeugnisses (Griff, Sohle, Front eines Autos) und Verzierungen (Muster auf Stoff) sind Designs; grafische Symbole, Icons und Schriftbilder ebenso, weil sie Erzeugnisse nach § 1 Nr. 2 DesignG sind. Die Richtlinie (EU) 2024/2823 erfasst ab 2027 ausdrücklich auch Bewegung, Übergänge und Animationen. Schutzgegenstand ist, was die Wiedergabe sichtbar zeigt (§ 37 DesignG): Zeigen die Abbildungen mehrere Ausführungsformen, fehlt „ein“ Design und die Eintragung ist nichtig (BGH Sporthelm, Sportbrille).",
      norms=["§ 1 DesignG", "§ 37 Abs. 1 DesignG", "Art. 3 GGV", "Art. 1 DesignRL", "Art. 2 DesignRL 2024"], cases=["des_bgh_sporthelm", "des_bgh_weinkaraffe", "des_eugh_ferrari"], related=["des_erzeugnis", "des_schutzgegenstand", "des_wiedergabe"]),
    c("des_erzeugnis", "Erzeugnis, komplexes Erzeugnis, bestimmungsgemäße Verwendung (§ 1 Nr. 2 bis 4 DesignG)", S,
      "Erzeugnis ist jeder industrielle oder handwerkliche Gegenstand einschließlich Verpackung, Ausstattung, grafischer Symbole und typografischer Schriftbilder sowie Einzelteile, die zu einem komplexen Erzeugnis zusammengebaut werden sollen; ein Computerprogramm ist kein Erzeugnis (§ 1 Nr. 2 DesignG). Ein komplexes Erzeugnis besteht aus mehreren austauschbaren Bauelementen (Nr. 3); bestimmungsgemäße Verwendung ist die Verwendung durch den Endbenutzer ohne Instandhaltung, Wartung und Reparatur (Nr. 4).",
      "Die Erzeugnisangabe in der Anmeldung (§ 11 Abs. 3 DesignG) ist Pflicht, bestimmt aber nicht den Schutzumfang (§ 11 Abs. 6 DesignG): Ein für „Stühle“ eingetragenes Design wird auch durch eine Lampe gleicher Form verletzt, wenn der Gesamteindruck übereinstimmt (EuGH Easy Sanitary: ältere Muster anderer Erzeugnisarten sind ebenfalls neuheitsschädlich). Bauelemente komplexer Erzeugnisse (Autoteile, Fahrradsattel) sind nur schutzfähig, soweit sie bei bestimmungsgemäßer Verwendung sichtbar bleiben (§ 4 DesignG). Ab 2027: auch nicht körperliche Erzeugnisse und grafische Benutzeroberflächen (Art. 2 DesignRL 2024).",
      norms=["§ 1 DesignG", "§ 4 DesignG", "§ 11 Abs. 3 DesignG", "§ 11 Abs. 6 DesignG", "Art. 3 GGV"], cases=["des_eugh_easy_sanitary", "des_eugh_monz"], related=["des_design_begriff", "des_bauelement_sichtbarkeit", "des_erzeugnisangabe"]),
    c("des_neuheit", "Neuheit (§ 2 Abs. 2 DesignG)", S,
      "Ein Design gilt als neu, wenn vor dem Anmeldetag (bei Priorität: dem Prioritätstag, § 13 Abs. 2 DesignG) kein identisches Design offenbart worden ist; identisch sind Designs, deren Merkmale sich nur in unwesentlichen Einzelheiten unterscheiden (§ 2 Abs. 2 DesignG, Art. 4 DesignRL, Art. 5 GGV).",
      "Die Neuheit ist ein Einzelvergleich mit jedem offenbarten älteren Design (§ 5 DesignG), gleich für welches Erzeugnis es bestimmt war und ob es in der Union bekannt sein konnte (Fachkreisklausel). Weil die Identitätsschwelle eng ist, scheitern Nichtigkeitsanträge meist nicht an der Neuheit, sondern an der Eigenart. Eigene Offenbarungen in den zwölf Monaten vor der Anmeldung schaden nicht (§ 6 DesignG). Das DPMA prüft die Neuheit nicht (§ 16 DesignG); sie wird erst im Nichtigkeitsverfahren (§ 33 Abs. 1 Nr. 2 DesignG) oder per Widerklage relevant. Anders als im Patentrecht gibt es keine Neuheitsschädlichkeit nachveröffentlichter älterer Anmeldungen; ältere, erst später bekannt gemachte Designs sind stattdessen relativer Nichtigkeitsgrund (§ 33 Abs. 2 Nr. 2 DesignG).",
      norms=["§ 2 Abs. 2 DesignG", "§ 5 DesignG", "§ 6 DesignG", "§ 13 Abs. 2 DesignG", "Art. 5 GGV", "Art. 4 DesignRL"], cases=["des_eugh_easy_sanitary", "des_bgh_verlaengerte_limousinen"], related=["des_eigenart", "des_offenbarung", "des_neuheitsschonfrist", "des_formenschatz"]),
    c("des_eigenart", "Eigenart (§ 2 Abs. 3 DesignG)", S,
      "Ein Design hat Eigenart, wenn sich der Gesamteindruck, den es beim informierten Benutzer hervorruft, von dem Gesamteindruck unterscheidet, den ein anderes, vor dem Anmeldetag offenbartes Design bei diesem Benutzer hervorruft; dabei wird der Grad der Gestaltungsfreiheit des Entwerfers berücksichtigt (§ 2 Abs. 3 DesignG, Art. 5 DesignRL, Art. 6 GGV).",
      "Eigenart bedeutet Unterschiedlichkeit, nicht Eigentümlichkeit oder Gestaltungshöhe wie nach altem Recht (BGH Verlängerte Limousinen). Geprüft wird im Einzelvergleich mit jedem konkreten älteren Design; eine Kombination von Merkmalen aus mehreren Entgegenhaltungen ist unzulässig (EuGH Karen Millen, BGH Meda Gate). Bei hoher Musterdichte und geringer Gestaltungsfreiheit genügen schon kleine Unterschiede (EuGH PepsiCo); technisch bedingte Übereinstimmungen gewichtet der informierte Benutzer gering. Eine bloße Farbänderung begründet Eigenart nur ausnahmsweise (BPatG Violette Trittleiter). Der Maßstab der Eigenart ist zugleich der Maßstab des Schutzumfangs (§ 38 Abs. 2 DesignG): Wer viel Abstand hält, bekommt viel Schutz (BGH Untersetzer).",
      norms=["§ 2 Abs. 3 DesignG", "§ 38 Abs. 2 DesignG", "Art. 6 GGV", "Art. 5 DesignRL"], cases=["des_eugh_pepsico", "des_eugh_karen_millen", "des_bgh_verlaengerte_limousinen", "des_bgh_untersetzer", "des_bgh_meda_gate", "des_bpatg_violette_trittleiter"], related=["des_informierter_benutzer", "des_gesamteindruck", "des_gestaltungsfreiheit", "des_formenschatz", "des_neuheit", "des_schutzumfang"]),
    c("des_informierter_benutzer", "Informierter Benutzer", S,
      "Der informierte Benutzer ist die Maßstabsfigur für Eigenart und Schutzumfang: eine Person, die das Erzeugnis benutzt, verschiedene Designs des betreffenden Sektors kennt, über gewisse Kenntnisse der üblichen Gestaltungselemente verfügt und die Erzeugnisse mit vergleichsweise großer Aufmerksamkeit benutzt; sie steht zwischen dem Durchschnittsverbraucher des Markenrechts und dem Fachmann (EuGH PepsiCo).",
      "Der informierte Benutzer ist weder Designer noch Techniker; er nimmt das Erzeugnis bei bestimmungsgemäßer Verwendung wahr (BGH Armbanduhr: Uhr am Handgelenk) und vergleicht die Designs nach Möglichkeit direkt, nicht aus der Erinnerung. Er muss das ältere Design nicht tatsächlich kennen; es genügt, dass er es kennen kann, etwa aus Internetangeboten (BGH Ballerinaschuh, EuGH Easy Sanitary). Bei Teilen komplexer Erzeugnisse ist der Benutzer des Gesamterzeugnisses maßgeblich.",
      norms=["§ 2 Abs. 3 DesignG", "§ 38 Abs. 2 DesignG", "Art. 6 GGV", "Art. 10 GGV"], cases=["des_eugh_pepsico", "des_bgh_armbanduhr", "des_bgh_ballerinaschuh"], related=["des_eigenart", "des_gesamteindruck", "des_schutzumfang"]),
    c("des_gesamteindruck", "Gesamteindruck", S,
      "Der Gesamteindruck ist der Eindruck, den das Design als Ganzes beim informierten Benutzer hervorruft; er entscheidet über Eigenart (§ 2 Abs. 3 DesignG) und Schutzumfang (§ 38 Abs. 2 DesignG). Verglichen werden die Designs in ihrer Gesamtheit, wobei prägende Merkmale stärker wiegen als Nebensächlichkeiten und technisch bedingte Merkmale zurücktreten.",
      "Prüfungsschritte: (1) Merkmale des Klagedesigns aus der Wiedergabe bestimmen (§ 37 DesignG), (2) Gestaltungsfreiheit und Formenschatz ermitteln, (3) Merkmale des angegriffenen Erzeugnisses feststellen, (4) Übereinstimmungen und Unterschiede gewichten, (5) Gesamtvergleich. Bei Schwarz-Weiß-Wiedergabe ist von der Farbe zu abstrahieren (BGH Schreibgeräte). Unterschiede in technisch bedingten Merkmalen sind nicht automatisch unbeachtlich (BGH Kinderwagen II). Das Gericht muss den Gesamteindruck der Entgegenhaltungen konkret feststellen; Abbildungen allein genügen nicht (BGH Meda Gate).",
      norms=["§ 2 Abs. 3 DesignG", "§ 38 Abs. 2 DesignG", "Art. 6 GGV", "Art. 10 GGV"], cases=["des_bgh_kinderwagen_ii", "des_bgh_meda_gate", "des_bgh_schreibgeraete", "des_bgh_armbanduhr"], related=["des_eigenart", "des_schutzumfang", "des_informierter_benutzer", "des_gestaltungsfreiheit"]),
    c("des_gestaltungsfreiheit", "Gestaltungsfreiheit des Entwerfers", S,
      "Der Grad der Gestaltungsfreiheit ist bei Eigenart und Schutzumfang zu berücksichtigen (§ 2 Abs. 3 S. 2, § 38 Abs. 2 S. 2 DesignG): Er ergibt sich aus technischen Vorgaben, gesetzlichen Anforderungen und der Musterdichte des Sektors. Große Freiheit verlangt größeren Abstand für Eigenart und gewährt größeren Schutzumfang; geringe Freiheit lässt kleine Unterschiede genügen und verengt den Schutz.",
      "Maßgeblich ist die Gestaltungsfreiheit des Entwerfers des Klagedesigns im Zeitpunkt seiner Anmeldung (BGH Untersetzer), nicht die des Nachahmers. Ein dichter Formenschatz (viele ähnliche Vorgestaltungen) wirkt wie geringe Gestaltungsfreiheit. Eine Selbstbeschränkung durch Trends oder Kundenwünsche schränkt die Freiheit nicht ein (EuGH-Rechtsprechung zu Art. 6 GGV).",
      norms=["§ 2 Abs. 3 DesignG", "§ 38 Abs. 2 DesignG", "Art. 6 GGV", "Art. 10 GGV"], cases=["des_bgh_untersetzer", "des_eugh_pepsico", "des_bgh_kinderwagen_ii"], related=["des_eigenart", "des_schutzumfang", "des_formenschatz"]),
    c("des_formenschatz", "Vorbekannter Formenschatz", S,
      "Der vorbekannte Formenschatz ist die Gesamtheit der vor dem Anmeldetag offenbarten Designs des Sektors; er ist Vergleichsmaßstab für Neuheit und Eigenart und bestimmt über die Musterdichte den Schutzumfang.",
      "Zum Formenschatz gehört alles, was den Fachkreisen der Union im normalen Geschäftsverlauf bekannt sein konnte (§ 5 DesignG), einschließlich Internetangeboten (BGH Ballerinaschuh). Der Vergleich erfolgt mit jedem einzelnen Muster, nicht mit einer Collage (EuGH Karen Millen, BGH Meda Gate). Im Verletzungsprozess muss der Beklagte den Formenschatz vortragen, der den Schutzumfang schmälert; der Kläger muss ihn nicht offenbaren (BGH Ballerinaschuh). Ein eigenes älteres Gemeinschaftsgeschmacksmuster zählt erst ab seiner Bekanntmachung, nicht ab Anmeldung (BGH Verlängerte Limousinen).",
      norms=["§ 2 DesignG", "§ 5 DesignG", "§ 38 Abs. 2 DesignG", "Art. 7 GGV"], cases=["des_bgh_ballerinaschuh", "des_bgh_meda_gate", "des_bgh_untersetzer", "des_bgh_verlaengerte_limousinen"], related=["des_offenbarung", "des_eigenart", "des_schutzumfang", "des_gestaltungsfreiheit"]),
    c("des_offenbarung", "Offenbarung und Fachkreisklausel (§ 5 DesignG)", S,
      "Ein Design ist offenbart, wenn es bekannt gemacht, ausgestellt, im Verkehr verwendet oder sonst der Öffentlichkeit zugänglich gemacht wurde, es sei denn, dies konnte den in der Union tätigen Fachkreisen des betreffenden Sektors im normalen Geschäftsverlauf vor dem Anmeldetag nicht bekannt sein; eine vertrauliche Mitteilung an Dritte ist keine Offenbarung (§ 5 DesignG, Art. 6 DesignRL, Art. 7 GGV).",
      "Die Fachkreisklausel schützt vor entlegenen Vorveröffentlichungen (etwa in einem Museum in Übersee), nicht vor jeder Offenbarung außerhalb der Union: Auch eine Präsentation gegenüber einem einzigen Unternehmen oder die Verteilung von Katalogen an Händler kann genügen (EuGH Gautzsch/Duna, Tatfrage). Wer sich auf eine Offenbarung beruft, muss sie beweisen (Datum, Umstände). Für das nicht eingetragene Gemeinschaftsgeschmacksmuster hat die Offenbarung eine zweite Funktion: Sie lässt den Schutz entstehen, aber nur bei Offenbarung in der Union (Art. 11 GGV).",
      norms=["§ 5 DesignG", "Art. 7 GGV", "Art. 11 GGV", "Art. 6 DesignRL"], cases=["des_eugh_gautzsch", "des_eugh_ferrari", "des_bgh_verlaengerte_limousinen"], related=["des_neuheit", "des_formenschatz", "des_neuheitsschonfrist", "des_ggm_nicht_eingetragen"]),
    c("des_neuheitsschonfrist", "Neuheitsschonfrist (§ 6 DesignG)", S,
      "Eine Offenbarung bleibt für Neuheit und Eigenart unberücksichtigt, wenn das Design in den zwölf Monaten vor dem Anmeldetag durch den Entwerfer, seinen Rechtsnachfolger oder als Folge von deren Handlungen durch Dritte offenbart wurde oder wenn die Offenbarung auf einem Missbrauch gegenüber dem Entwerfer beruht (§ 6 DesignG, Art. 6 Abs. 2, 3 DesignRL, Art. 7 Abs. 2, 3 GGV).",
      "Die Schonfrist erlaubt den Markttest vor der Anmeldung; sie ist die wichtigste Abweichung vom Patentrecht (dort nur sechs Monate und nur bei Missbrauch oder Ausstellung, § 3 Abs. 5 PatG). Sie schützt nur gegen die eigene Offenbarung, nicht gegen unabhängige Parallelentwicklungen Dritter in der Zwischenzeit, und begründet keine Priorität. Nach Ablauf der zwölf Monate ist die Eintragung nichtig; es bleibt das nicht eingetragene Gemeinschaftsgeschmacksmuster für drei Jahre ab erster Offenbarung in der Union.",
      norms=["§ 6 DesignG", "Art. 7 GGV", "Art. 6 DesignRL"], cases=[], related=["des_offenbarung", "des_neuheit", "des_ggm_nicht_eingetragen", "des_prioritaet"]),
    c("des_technisch_bedingt", "Ausschließlich technisch bedingte Merkmale (§ 3 Abs. 1 Nr. 1 DesignG)", S,
      "Erscheinungsmerkmale, die ausschließlich durch die technische Funktion des Erzeugnisses bedingt sind, sind vom Designschutz ausgeschlossen (§ 3 Abs. 1 Nr. 1 DesignG, Art. 7 Abs. 1 DesignRL, Art. 8 Abs. 1 GGV). Das ist der Fall, wenn die technische Funktion der einzige Faktor war, der die Merkmale bestimmt hat, und ästhetische Erwägungen keine Rolle spielten (EuGH DOCERAM).",
      "Der EuGH hat den Mehrheit-der-Formen-Test verworfen: Dass andere Formen dieselbe Funktion erfüllen könnten, beweist noch keine Gestaltungsfreiheit; zu prüfen ist objektiv anhand aller Umstände (Werbung, Patentschriften, Gestaltungsalternativen). Die Prüfung erfolgt Merkmal für Merkmal; nichtig ist das Design nur, wenn alle prägenden Merkmale technisch bedingt sind (BGH Tellerschleifgerät, EuG Lego). Ein Patent für dasselbe Erzeugnis schließt den Designschutz nicht aus, seine Offenlegungsschrift ist aber Indiz (BGH Papierspender). Technisch bedingte Merkmale werden im Übrigen beim Gesamteindruck gering gewichtet.",
      norms=["§ 3 Abs. 1 DesignG", "Art. 8 GGV", "Art. 7 DesignRL"], cases=["des_eugh_doceram", "des_bgh_papierspender", "des_bgh_tellerschleifgeraet", "des_eug_lego", "des_eugh_brompton"], related=["des_verbindungselemente", "des_nichtigkeit", "des_urheberrecht_kumulation"]),
    c("des_verbindungselemente", "Verbindungselemente und modulare Systeme (§ 3 Abs. 1 Nr. 2, Abs. 2 DesignG)", S,
      "Merkmale, die zwangsläufig in genauer Form und Abmessung nachgebildet werden müssen, damit das Erzeugnis mit einem anderen mechanisch verbunden werden kann („must fit“), sind ausgeschlossen (§ 3 Abs. 1 Nr. 2 DesignG); die Ausnahme gilt nicht für Merkmale, die den Zusammenbau austauschbarer Teile in einem Bauteilesystem ermöglichen (§ 3 Abs. 2 DesignG, Lego-Klausel).",
      "Zweck: Interoperabilität sichern (Staubsaugerdüse, Anhängerkupplung), ohne Systeme wie Klemmbausteine oder Regalsysteme schutzlos zu stellen. Nach EuG Lego ist die Rückausnahme auch zu prüfen, wenn die Merkmale zugleich als technisch bedingt (§ 3 Abs. 1 Nr. 1 DesignG) angegriffen werden. Formgebundene Ersatzteile („must match“, etwa Kotflügel) fallen nicht unter Nr. 2, sondern unter § 4 DesignG und die Reparaturklausel des § 40a DesignG.",
      norms=["§ 3 Abs. 1 DesignG", "§ 3 Abs. 2 DesignG", "Art. 8 GGV"], cases=["des_eug_lego"], related=["des_technisch_bedingt", "des_reparaturklausel"]),
    c("des_bauelement_sichtbarkeit", "Bauelemente komplexer Erzeugnisse und Sichtbarkeit (§ 4 DesignG)", S,
      "Ein Design an einem Bauelement eines komplexen Erzeugnisses ist nur neu und eigenartig, wenn das Bauelement bei bestimmungsgemäßer Verwendung des komplexen Erzeugnisses sichtbar bleibt und die sichtbaren Merkmale selbst neu und eigenartig sind (§ 4 DesignG, Art. 3 Abs. 3, 4 DesignRL, Art. 4 Abs. 2, 3 GGV).",
      "Innen liegende Teile (Motorblock, Filter) sind schutzlos. Sichtbarkeit ist aus Sicht des Endbenutzers und eines außenstehenden Beobachters zu beurteilen und muss nicht in jedem Moment bestehen; bestimmungsgemäße Verwendung umfasst auch Aufbewahrung und Transport, nicht Wartung und Reparatur (EuGH Monz/Büchel, BGH Sattelunterseite II). Passt ein Bauelement zu mehreren komplexen Erzeugnissen, genügt Sichtbarkeit bei einem (BPatG Sattelunterseite II). Die Richtlinie 2024/2823 spricht von „üblicher Verwendung“.",
      norms=["§ 4 DesignG", "§ 1 DesignG", "Art. 3 DesignRL", "Art. 4 GGV"], cases=["des_eugh_monz", "des_bgh_sattelunterseite_ii", "des_bpatg_sattelunterseite_ii", "des_bgh_baugruppe"], related=["des_erzeugnis", "des_reparaturklausel", "des_technisch_bedingt"]),
    c("des_ordre_public", "Öffentliche Ordnung, gute Sitten, Hoheitszeichen (§ 3 Abs. 1 Nr. 3, 4 DesignG)", S,
      "Vom Schutz ausgeschlossen sind Designs, die gegen die öffentliche Ordnung oder die guten Sitten verstoßen (§ 3 Abs. 1 Nr. 3 DesignG), und solche, die Wappen, Flaggen, amtliche Prüfzeichen oder andere Zeichen von öffentlichem Interesse missbräuchlich benutzen (Nr. 4, Art. 6ter PVÜ).",
      "Das sind die einzigen materiellen Hindernisse, die das DPMA im Eintragungsverfahren prüft (§ 18 DesignG); im Nichtigkeitsverfahren kann Nr. 4 nur der Betroffene geltend machen (§ 34 S. 3 DesignG). Die dekorative Abbildung einer Euro-Münze verstößt nicht gegen Nr. 4 (BGH Euro-Billy zum GeschmMG).",
      norms=["§ 3 Abs. 1 DesignG", "§ 18 DesignG", "§ 34 DesignG", "Art. 9 GGV", "Art. 8 DesignRL"], cases=[], related=["des_pruefung_dpma", "des_nichtigkeit"]),
    # ------------------------------------------------------------------ Berechtigte und Rechtsverkehr
    c("des_entwerfer_recht", "Recht auf das eingetragene Design und formelle Berechtigung (§§ 7, 8 DesignG)", V,
      "Das Recht auf das eingetragene Design steht dem Entwerfer oder seinem Rechtsnachfolger zu, bei mehreren Entwerfern gemeinschaftlich (§ 7 Abs. 1 DesignG, Art. 14 GGV). Anmelder und eingetragener Rechtsinhaber gelten in Verfahren als berechtigt (§ 8 DesignG).",
      "Entwerfer ist, wer die Erscheinungsform gestaltet hat; Auftraggeber und Agenturen werden nur durch Vertrag Rechtsnachfolger. Beim nicht eingetragenen Gemeinschaftsgeschmacksmuster muss der Kläger die Inhaberschaft beweisen; die erste Offenbarung begründet keine Vermutung (BGH Bolerojäckchen). Der Entwerfer hat ein Recht auf Nennung (§ 10 DesignG, Art. 18 GGV).",
      norms=["§ 7 DesignG", "§ 8 DesignG", "§ 10 DesignG", "Art. 14 GGV"], cases=["des_bgh_bolerojaeckchen"], related=["des_arbeitnehmerdesign", "des_vindikation"]),
    c("des_arbeitnehmerdesign", "Arbeitnehmerdesign (§ 7 Abs. 2 DesignG)", V,
      "Wird ein Design von einem Arbeitnehmer in Ausübung seiner Aufgaben oder nach Weisung des Arbeitgebers entworfen, steht das Recht am eingetragenen Design kraft Gesetzes dem Arbeitgeber zu, sofern nichts anderes vereinbart ist (§ 7 Abs. 2 DesignG, Art. 14 Abs. 3 GGV).",
      "Anders als bei Diensterfindungen (§§ 6, 9 ArbnErfG) bedarf es weder einer Inanspruchnahme noch einer gesetzlichen Vergütung; das ArbnErfG gilt für Designs nicht. Das Entwerferpersönlichkeitsrecht (Nennung, § 10 DesignG) bleibt beim Arbeitnehmer. Freie Designer und Werkunternehmer fallen nicht unter Abs. 2; hier ist eine ausdrückliche Rechtsübertragung nötig, sonst bleibt das Recht beim Entwerfer und der Auftraggeber hat allenfalls eine Lizenz aus dem Vertragszweck.",
      norms=["§ 7 Abs. 2 DesignG", "Art. 14 GGV"], cases=["des_bgh_bolerojaeckchen"], related=["des_entwerfer_recht", "des_vindikation"]),
    c("des_vindikation", "Ansprüche gegen Nichtberechtigte (§ 9 DesignG)", V,
      "Ist ein Design auf einen Nichtberechtigten eingetragen, kann der Berechtigte Übertragung oder Einwilligung in die Löschung verlangen (§ 9 Abs. 1 DesignG), nur durch Klage binnen drei Jahren ab Bekanntmachung, außer bei Bösgläubigkeit (Abs. 2); mit der Umschreibung erlöschen Lizenzen, der frühere Inhaber erhält ein Weiterbenutzungsrecht gegen Vergütung (Abs. 3).",
      "Die Vindikation ist der Weg des bestohlenen Entwerfers; daneben ist die Nichtberechtigung kein Nichtigkeitsgrund nach § 33 DesignG (anders Art. 25 Abs. 1 lit. c GGV, Art. 11 Abs. 1 lit. c DesignRL, den Deutschland über § 9 DesignG umsetzt). Die Klage gehört vor das Designgericht (§ 52 DesignG) und wird im Register vermerkt (Abs. 4).",
      norms=["§ 9 DesignG", "Art. 15 GGV", "Art. 11 DesignRL"], cases=[], related=["des_entwerfer_recht", "des_nichtigkeit", "des_designstreitsachen"]),
    c("des_lizenz", "Lizenz und Rechtsübergang (§§ 29 bis 32 DesignG)", V,
      "Das eingetragene Design und die Anmeldung sind übertragbar, verpfändbar und lizenzierbar (§§ 29, 30, 32 DesignG). Lizenzen können ausschließlich oder einfach und räumlich beschränkt sein (§ 31 Abs. 1 DesignG); Überschreitungen von Dauer, Nutzungsform, Erzeugnissen, Gebiet oder Qualität sind Designverletzungen (§ 31 Abs. 2 DesignG).",
      "Klagebefugnis: Der einfache Lizenznehmer klagt nur mit Zustimmung des Rechtsinhabers, der ausschließliche auch nach fruchtloser Aufforderung (§ 31 Abs. 3 DesignG); jeder Lizenznehmer kann der Klage für seinen eigenen Schaden beitreten (Abs. 4). Sukzessionsschutz: Rechtsübergang und spätere Lizenzen berühren frühere Lizenzen nicht (Abs. 5). Registereintragung des Übergangs ist deklaratorisch, aber Voraussetzung für die Legitimation nach § 8 DesignG.",
      norms=["§ 29 DesignG", "§ 30 DesignG", "§ 31 DesignG", "§ 32 DesignG", "Art. 32 GGV"], cases=[], related=["des_entwerfer_recht", "des_unterlassung"]),
    # ------------------------------------------------------------------ Anmeldung und Eintragung
    c("des_anmeldung", "Anmeldung beim DPMA (§ 11 DesignG, DesignV)", A,
      "Die Anmeldung ist beim DPMA (oder einem Patentinformationszentrum) einzureichen und muss Eintragungsantrag, Angaben zur Identität des Anmelders und eine bekanntmachungsfähige Wiedergabe enthalten (§ 11 Abs. 2 DesignG); Pflicht ist außerdem die Erzeugnisangabe (§ 11 Abs. 3 DesignG). Form und Inhalt regelt die DesignV (§§ 3 bis 14 DesignV).",
      "Gebühren: 60 EUR elektronisch, 70 EUR in Papier (Nr. 341 000, 341 100 GV PatKostG), Zahlungsfrist drei Monate nach § 6 PatKostG, sonst gilt die Anmeldung als zurückgenommen. Zusätzlich möglich: Beschreibung (max. 100 Wörter), Aufschiebungsantrag, Warenklassen, Entwerferbenennung. Die Wiedergabe ist das Herzstück: bis zu zehn Darstellungen, die ein einheitliches Design zeigen müssen (§ 7 DesignV, BGH Sporthelm). Die Anmeldung kann jederzeit zurückgenommen werden (§ 11 Abs. 7 DesignG). Alternativen: Unionsgeschmacksmuster beim EUIPO (Art. 35 Abs. 1 GGV; die Weiterleitung über das DPMA nach § 62 DesignG ist seit 1.5.2025 entfallen) oder internationale Eintragung nach dem Haager Abkommen (§ 67 DesignG).",
      norms=["§ 11 DesignG", "§ 3 DesignV", "§ 7 DesignV", "§ 9 DesignV", "§ 10 DesignV"], cases=["des_bgh_sporthelm"], related=["des_anmeldetag", "des_wiedergabe", "des_erzeugnisangabe", "des_sammelanmeldung", "des_pruefung_dpma"]),
    c("des_anmeldetag", "Anmeldetag (§ 13 DesignG)", A,
      "Anmeldetag ist der Tag, an dem die Unterlagen mit Antrag, Identität des Anmelders und Wiedergabe beim DPMA oder einem bestimmten Patentinformationszentrum eingehen (§ 13 Abs. 1 DesignG); bei wirksamer Priorität tritt der Prioritätstag an seine Stelle (§ 13 Abs. 2 DesignG).",
      "Der Anmeldetag ist Stichtag für Neuheit, Eigenart, Neuheitsschonfrist, Vorbenutzungsrecht und Zeitrang gegenüber anderen Designs; die Schutzdauer von 25 Jahren läuft ab Anmeldetag (§ 27 Abs. 2 DesignG), der Schutz selbst beginnt erst mit Eintragung (§ 27 Abs. 1 DesignG). Fehlende Erzeugnisangabe oder Gebühr verschieben den Anmeldetag nicht; fehlende Wiedergabe schon. Beim Unionsgeschmacksmuster: Art. 38 GGV.",
      norms=["§ 13 DesignG", "§ 11 Abs. 2 DesignG", "§ 27 DesignG", "Art. 38 GGV"], cases=[], related=["des_anmeldung", "des_prioritaet", "des_schutzdauer"]),
    c("des_sammelanmeldung", "Sammelanmeldung (§ 12 DesignG)", A,
      "Bis zu 100 Designs können in einer Sammelanmeldung zusammengefasst werden (§ 12 Abs. 1 DesignG); seit 2014 ohne Bindung an eine Warenklasse. Die Sammelanmeldung kann jederzeit unter Wahrung des Anmeldetags geteilt werden, gegebenenfalls gegen Nachzahlung der Gebührendifferenz (§ 12 Abs. 2 DesignG).",
      "Gebühr: 60 EUR elektronisch für zwei bis zehn Designs, je weiteres 6 EUR (Nr. 341 200 GV PatKostG). Jedes Design der Sammelanmeldung ist ein eigenes Schutzrecht mit eigener Nummer (…-0001, -0002), das gesondert aufrechterhalten, übertragen und für nichtig erklärt werden kann. Bei unzureichender Gebührenzahlung bestimmt der Anmelder, sonst das DPMA, welche Designs gedeckt sind (§ 16 Abs. 2 DesignG). Unionsgeschmacksmuster: bis zu 50 Muster je Sammelanmeldung (Art. 37 GGV).",
      norms=["§ 12 DesignG", "§ 16 Abs. 2 DesignG", "§ 5 DesignV", "§ 12 DesignV", "Art. 37 GGV"], cases=[], related=["des_anmeldung", "des_wiedergabe"]),
    c("des_wiedergabe", "Wiedergabe des Designs (§ 7 DesignV)", A,
      "Die Wiedergabe erfolgt durch fotografische oder sonstige grafische Darstellungen, bis zu zehn je Design, auf neutralem Hintergrund, ohne Beiwerk und Text (§ 7 DesignV); sie legt den Schutzgegenstand fest (§ 37 Abs. 1 DesignG): Geschützt ist nur, was sichtbar wiedergegeben ist.",
      "Fehlerquellen: Mehrere Darstellungen mit abweichenden Merkmalen (verschiedene Farben, Ausstattungsvarianten) zeigen nicht „ein“ Design und führen zur Nichtigkeit (BGH Sporthelm, Sportbrille, BPatG Schalungsbrett); Abweichungen können aber durch Auslegung überwunden werden, wenn der Schutzgegenstand als Schnittmenge erkennbar bleibt (BGH Weinkaraffe, Schneidebrett). Schwarz-Weiß-Fotos schützen die Form und den Hell-Dunkel-Kontrast unabhängig von der Farbe (BGH Schreibgeräte, Sportbrille). Strategisch: eine Variante je Design, Varianten in der Sammelanmeldung. Die DesignRL 2024 erlaubt ab 2027 auch Videos und 3D-Modelle sowie Disclaimer (Art. 26 DesignRL 2024).",
      norms=["§ 7 DesignV", "§ 37 Abs. 1 DesignG", "§ 11 Abs. 2 DesignG", "Art. 26 DesignRL 2024"], cases=["des_bgh_sporthelm", "des_bgh_sportbrille", "des_bgh_weinkaraffe", "des_bgh_schneidebrett", "des_bpatg_schalungsbrett", "des_bgh_schreibgeraete"], related=["des_schutzgegenstand", "des_anmeldung", "des_design_begriff"]),
    c("des_erzeugnisangabe", "Erzeugnisangabe und Warenklassen (§ 11 Abs. 3, 6 DesignG, § 9 DesignV)", A,
      "Die Anmeldung muss die Erzeugnisse angeben, in die das Design aufgenommen oder bei denen es verwendet werden soll (§ 11 Abs. 3 DesignG), nach der amtlichen Warenliste (Locarno-Klassifikation) mit bis zu fünf Begriffen (§ 9 DesignV); die Angabe und die Warenklassen haben keinen Einfluss auf den Schutzumfang (§ 11 Abs. 6 DesignG).",
      "Die Erzeugnisangabe dient der Recherche und der Bestimmung des Erzeugnisses, dessen informierter Benutzer und dessen Gestaltungsfreiheit maßgeblich sind; sie begrenzt den Schutz aber nicht auf die Warenklasse (anders als das Waren- und Dienstleistungsverzeichnis im Markenrecht). Das DPMA bestimmt die Klassen von Amts wegen (§ 19 Abs. 2 DesignG).",
      norms=["§ 11 Abs. 3 DesignG", "§ 11 Abs. 6 DesignG", "§ 9 DesignV", "§ 19 DesignG", "Art. 36 GGV"], cases=["des_eugh_easy_sanitary"], related=["des_erzeugnis", "des_anmeldung"]),
    c("des_prioritaet", "Priorität (§§ 14, 15 DesignG)", A,
      "Wer die Priorität einer früheren ausländischen Anmeldung nach der PVÜ beansprucht (sechs Monate), muss binnen 16 Monaten nach dem Prioritätstag Zeit, Land und Aktenzeichen angeben und eine Abschrift einreichen (§ 14 Abs. 1 DesignG); die Ausstellungspriorität setzt Anmeldung binnen sechs Monaten nach erstmaliger Zurschaustellung auf einer amtlichen oder bestimmten Ausstellung voraus (§ 15 DesignG).",
      "Der Prioritätstag ersetzt den Anmeldetag für Neuheit, Eigenart, Neuheitsschonfrist, ältere Rechte und Vorbenutzungsrecht (§ 13 Abs. 2 DesignG). Die Prioritätsfrist beträgt sechs Monate wie bei Marken, nicht zwölf wie bei Patenten. Innere Priorität aus einer früheren deutschen Anmeldung gibt es nicht. Beim Unionsgeschmacksmuster: Art. 41 bis 44 GGV.",
      norms=["§ 14 DesignG", "§ 15 DesignG", "§ 13 Abs. 2 DesignG", "§ 11 DesignV", "Art. 41 GGV"], cases=[], related=["des_anmeldetag", "des_neuheitsschonfrist"]),
    c("des_pruefung_dpma", "Prüfung, Eintragung, Bekanntmachung (§§ 16 bis 20 DesignG)", A,
      "Das DPMA prüft Gebührenzahlung, Anmeldetagserfordernisse und sonstige Formerfordernisse (§ 16 Abs. 1 DesignG) sowie die Eintragungshindernisse des § 18 DesignG (kein Design, Sittenverstoß, Hoheitszeichen); Neuheit und Eigenart werden nicht geprüft. Mängel werden mit Frist gerügt, sonst wird zurückgewiesen (§ 16 Abs. 3 DesignG); die Eintragung erfolgt ohne Prüfung der Berechtigung (§ 19 DesignG) und wird mit Wiedergabe bekannt gemacht (§ 20 DesignG).",
      "Folge des Registerprinzips: Das eingetragene Design ist ein ungeprüftes Recht mit Vermutung der Rechtsgültigkeit (§ 39 DesignG); Angreifer sind auf das Nichtigkeitsverfahren verwiesen. Rechtsbehelfe gegen Zurückweisung: Weiterbehandlung bei versäumter Amtsfrist (§ 17 DesignG), sonst Beschwerde zum BPatG (§ 23 Abs. 4 DesignG). Verfahrensdauer typischerweise wenige Wochen bis Monate; Schutz entsteht mit Eintragung (§ 27 Abs. 1 DesignG).",
      norms=["§ 16 DesignG", "§ 17 DesignG", "§ 18 DesignG", "§ 19 DesignG", "§ 20 DesignG", "Art. 45 GGV", "Art. 47 GGV"], cases=[], related=["des_anmeldung", "des_ordre_public", "des_weiterbehandlung", "des_vermutung_rechtsgueltigkeit"]),
    c("des_aufschiebung", "Aufschiebung der Bildbekanntmachung (§ 21 DesignG)", A,
      "Mit der Anmeldung kann beantragt werden, die Bekanntmachung der Wiedergabe um 30 Monate ab Anmeldetag aufzuschieben (§ 21 Abs. 1 DesignG); bekannt gemacht wird dann nur die Eintragung. Der Schutz muss innerhalb der Aufschiebungsfrist durch Zahlung der Erstreckungsgebühr auf die volle Schutzdauer erstreckt werden, sonst endet er mit Ablauf der 30 Monate (§ 21 Abs. 2, 4 DesignG).",
      "Zweck: Geheimhaltung bis zur Markteinführung (Mode, Automobil). Während der Aufschiebung besteht nur Nachahmungsschutz: Der Verletzer muss das Design gekannt haben (§ 38 Abs. 3 DesignG). Gebühren: 30 EUR je Design bei Anmeldung mit Aufschiebung (Nr. 341 400 GV PatKostG), Erstreckung 40 EUR (Nr. 341 600). Die Wiedergabe kann bei Aufschiebung durch einen flächenmäßigen Designabschnitt ersetzt werden (§ 11 Abs. 2 S. 2 DesignG, § 8 DesignV). Unionsgeschmacksmuster: Art. 50 GGV.",
      norms=["§ 21 DesignG", "§ 38 Abs. 3 DesignG", "§ 11 Abs. 2 DesignG", "§ 19 DesignV", "Art. 50 GGV"], cases=[], related=["des_anmeldung", "des_schutzdauer", "des_benutzung"]),
    c("des_weiterbehandlung", "Weiterbehandlung und Wiedereinsetzung (§ 17 DesignG, § 23 Abs. 3 S. 3 DesignG)", A,
      "Wird die Anmeldung wegen Versäumung einer vom DPMA gesetzten Frist zurückgewiesen, wird der Beschluss wirkungslos, wenn der Anmelder binnen eines Monats nach Zustellung Weiterbehandlung beantragt, die Handlung nachholt und die Gebühr zahlt (§ 17 DesignG); kein Verschuldensmaßstab, aber keine Wiedereinsetzung in diese Frist (§ 17 Abs. 3 DesignG). Für andere Fristen gilt die Wiedereinsetzung nach § 123 PatG entsprechend (§ 23 Abs. 3 S. 3 DesignG).",
      "Weiterbehandlungsgebühr 100 EUR (Nr. 346 000 GV PatKostG). Die Weiterbehandlung gilt nur für Amtsfristen im Anmeldeverfahren, nicht für gesetzliche Fristen (Gebührenzahlung nach § 6 PatKostG, Aufrechterhaltung, Prioritätsfrist) und nicht für das Nichtigkeitsverfahren. Verspätete Aufrechterhaltungsgebühren: Zuschlagsfrist nach § 7 PatKostG mit 50 EUR Verspätungszuschlag.",
      norms=["§ 17 DesignG", "§ 23 Abs. 3 DesignG", "§ 13 DesignV", "§ 123 PatG"], cases=[], related=["des_pruefung_dpma", "des_beschwerde_bpatg", "des_schutzdauer"]),
    c("des_beschwerde_bpatg", "Beschwerde zum BPatG und Rechtsbeschwerde (§ 23 DesignG)", A,
      "Gegen Beschlüsse des DPMA in Designsachen findet die Beschwerde zum BPatG statt (§ 23 Abs. 4 DesignG; Frist ein Monat, Gebühr 200 EUR, Nr. 401 300 GV PatKostG), über die ein Senat mit drei rechtskundigen Mitgliedern entscheidet (Nichtigkeitssachen: 30. Senat). Die Rechtsbeschwerde zum BGH ist nur bei Zulassung oder wegen absoluter Verfahrensmängel statthaft (§ 23 Abs. 5 DesignG, § 100 PatG).",
      "Im Eintragungsverfahren entscheiden Designstellen, im Nichtigkeitsverfahren Designabteilungen mit drei rechtskundigen Mitgliedern (§ 23 Abs. 1, 2 DesignG). Das rechtliche Gehör ist auch im Beschwerdeverfahren zu wahren: Das BPatG darf nicht entscheiden, bevor eine angekündigte Beschwerdebegründung eingereicht werden konnte (BGH Heizkörperdesign). Vertretungszwang gibt es vor dem BPatG nicht, wohl aber den Inlandsvertreter (§ 58 DesignG).",
      norms=["§ 23 DesignG", "§ 58 DesignG", "§ 100 PatG"], cases=["des_bgh_heizkoerperdesign"], related=["des_nichtigkeitsverfahren_dpma", "des_weiterbehandlung", "des_pruefung_dpma"]),
    c("des_schutzdauer", "Entstehung, Schutzdauer, Aufrechterhaltung (§§ 27, 28 DesignG)", A,
      "Der Schutz entsteht mit der Eintragung (§ 27 Abs. 1 DesignG) und dauert bis zu 25 Jahre ab Anmeldetag (§ 27 Abs. 2 DesignG); er wird durch Aufrechterhaltungsgebühren für das 6. bis 10., 11. bis 15., 16. bis 20. und 21. bis 25. Jahr verlängert (§ 28 DesignG), sonst endet er und das Design wird gelöscht (§ 36 Abs. 1 Nr. 1 DesignG).",
      "Gebühren 90, 120, 150 und 180 EUR je Design (Nr. 342 100 bis 342 400 GV PatKostG), fällig am letzten Tag des Monats, in dem der Abschnitt endet (§ 3 Abs. 2, § 7 PatKostG), mit Zuschlagsfrist und 50 EUR Verspätungszuschlag. Kein Schutz vor Eintragung (anders § 33 PatG); Kläger aus der Anmeldung gibt es nicht. Unionsgeschmacksmuster: fünf Jahre, verlängerbar bis 25 (Art. 12 GGV); nicht eingetragenes Muster drei Jahre ab Offenbarung (Art. 11 GGV).",
      norms=["§ 27 DesignG", "§ 28 DesignG", "§ 36 DesignG", "§ 19 DesignV", "Art. 12 GGV"], cases=[], related=["des_anmeldetag", "des_aufschiebung", "des_weiterbehandlung"]),
    # ------------------------------------------------------------------ Nichtigkeit
    c("des_nichtigkeit", "Nichtigkeitsgründe (§ 33 DesignG)", N,
      "Ein eingetragenes Design ist nichtig, wenn es kein Design ist, nicht neu ist oder keine Eigenart hat oder nach § 3 DesignG ausgeschlossen ist (§ 33 Abs. 1 DesignG, absolute Gründe, Feststellung auf Antrag jedermanns). Es wird für nichtig erklärt, wenn es ein Urheberrecht verletzt, in den Schutzumfang eines älteren Designs fällt oder ein Zeichen mit Unterscheidungskraft benutzt (§ 33 Abs. 2 DesignG, relative Gründe, nur auf Antrag des Rechtsinhabers).",
      "Die Nichtigkeit wird durch Beschluss des DPMA (§ 34a DesignG) oder durch Urteil auf Widerklage (§ 52b DesignG) festgestellt oder erklärt (§ 33 Abs. 3 DesignG) und wirkt ex tunc (Abs. 4), auch nach Schutzende (Abs. 5). Praktisch wichtigste Gründe: fehlende Eigenart (§ 2 Abs. 3 DesignG), technische Bedingtheit (§ 3 Abs. 1 Nr. 1 DesignG), fehlender einheitlicher Schutzgegenstand (§ 33 Abs. 1 Nr. 1 DesignG, BGH Sporthelm) und ältere Designs, die erst nach dem Anmeldetag bekannt gemacht wurden (§ 33 Abs. 2 Nr. 2 DesignG). Nichtberechtigung ist kein Nichtigkeitsgrund (dafür § 9 DesignG). Teilweise Aufrechterhaltung nach § 35 DesignG. Unionsgeschmacksmuster: Art. 25 GGV.",
      norms=["§ 33 DesignG", "§ 34 DesignG", "§ 35 DesignG", "Art. 25 GGV", "Art. 11 DesignRL"], cases=["des_bgh_sporthelm", "des_eugh_doceram", "des_bpatg_violette_trittleiter"], related=["des_nichtigkeitsverfahren_dpma", "des_widerklage_nichtigkeit", "des_teilweise_aufrechterhaltung", "des_neuheit", "des_eigenart", "des_technisch_bedingt"]),
    c("des_nichtigkeitsverfahren_dpma", "Nichtigkeitsverfahren vor dem DPMA (§ 34a DesignG)", N,
      "Der Antrag auf Feststellung oder Erklärung der Nichtigkeit ist schriftlich mit Tatsachen und Beweismitteln beim DPMA zu stellen (§ 34a Abs. 1 DesignG, § 21 DesignV; Gebühr 300 EUR je Design, Nr. 346 100 GV PatKostG). Das DPMA stellt ihn dem Inhaber zu; widerspricht dieser nicht binnen eines Monats, wird die Nichtigkeit ohne Sachprüfung festgestellt oder erklärt (§ 34a Abs. 2 DesignG); sonst entscheidet die Designabteilung nach Anhörung durch Beschluss mit Kostenentscheidung (§ 34a Abs. 3 bis 5 DesignG).",
      "Seit 1.1.2014 (vorher Löschungsklage vor den Landgerichten). Antragsbefugnis nach § 34 DesignG (Popularantrag bei absoluten Gründen). Unzulässig, soweit über denselben Streitgegenstand zwischen den Parteien bereits unanfechtbar entschieden wurde (§ 34a Abs. 1 S. 4 DesignG). Beschwerde zum BPatG, 30. Senat (§ 23 Abs. 4 DesignG), Rechtsbeschwerde bei Zulassung (BGH Sporthelm, Sattelunterseite II). Der Verletzungsprozess kann ausgesetzt werden, muss es, wenn das Gericht das Design für nichtig hält (§ 34b DesignG); ein abgemahnter Dritter kann beitreten (§ 34c DesignG). Verfahrenskostenhilfe nach § 24 DesignG.",
      norms=["§ 34a DesignG", "§ 34 DesignG", "§ 34b DesignG", "§ 34c DesignG", "§ 21 DesignV", "§ 22 DesignV", "§ 23 DesignG"], cases=["des_bgh_sporthelm", "des_bgh_sattelunterseite_ii", "des_bpatg_sattelunterseite_ii", "des_bpatg_violette_trittleiter", "des_bpatg_schalungsbrett", "des_bgh_heizkoerperdesign"], related=["des_nichtigkeit", "des_widerklage_nichtigkeit", "des_beschwerde_bpatg", "des_teilweise_aufrechterhaltung"]),
    c("des_widerklage_nichtigkeit", "Nichtigkeitswiderklage und Registerprinzip (§§ 52a, 52b DesignG)", N,
      "Im Verletzungsprozess kann sich der Beklagte auf die fehlende Rechtsgültigkeit nur durch Widerklage auf Feststellung oder Erklärung der Nichtigkeit oder durch Antrag beim DPMA berufen, nicht durch bloße Einrede (§ 52a DesignG; Ausnahme: einstweilige Verfügung). Für die Widerklage ist das Designgericht zuständig, wenn sie mit der Verletzungsklage zusammenhängt (§ 52b Abs. 1 DesignG); nach rechtskräftigem DPMA-Beschluss ist sie unzulässig (§ 52b Abs. 2 DesignG).",
      "Das Gericht kann auf Antrag des Inhabers aussetzen und den Widerkläger ins DPMA-Verfahren verweisen (§ 52b Abs. 3 DesignG); Widerklage und Ergebnis werden im Register vermerkt (Abs. 4). Das System entspricht Art. 84 bis 86 GGV für Unionsgeschmacksmuster; beim nicht eingetragenen Unionsgeschmacksmuster bleibt die Einrede zulässig (Art. 85 Abs. 2 GGV, EuGH Karen Millen). Für Streitigkeiten ab 2014 (§ 74 Abs. 3 DesignG).",
      norms=["§ 52a DesignG", "§ 52b DesignG", "§ 39 DesignG", "Art. 84 GGV", "Art. 85 GGV", "Art. 86 GGV"], cases=["des_eugh_karen_millen", "des_bgh_kinderwagen_i"], related=["des_nichtigkeit", "des_nichtigkeitsverfahren_dpma", "des_vermutung_rechtsgueltigkeit", "des_designstreitsachen"]),
    c("des_teilweise_aufrechterhaltung", "Teilweise Aufrechterhaltung und Löschung (§§ 35, 36 DesignG)", N,
      "Ein Design kann in geänderter Form bestehen bleiben, wenn die Nichtigkeit nur Teile betrifft (Teilnichtigkeit oder Teilverzicht) und das Design seine Identität behält (§ 35 DesignG, Art. 11 Abs. 7 DesignRL); eine geänderte Wiedergabe ist einzureichen. Gelöscht wird bei Schutzende, Verzicht, Einwilligung und rechtskräftiger Nichtigkeit (§ 36 DesignG).",
      "Eine Erweiterung ist ausgeschlossen: Die geänderte Form muss im ursprünglichen Design enthalten sein (etwa Verzicht auf ein zusätzliches Element oder Beschränkung auf einen Teil). Die Einwilligung in die Löschung nach § 33 Abs. 6 DesignG lässt die Schutzwirkungen von Anfang an entfallen und beendet ein anhängiges Nichtigkeitsverfahren.",
      norms=["§ 35 DesignG", "§ 36 DesignG", "§ 33 Abs. 6 DesignG", "§ 20 DesignV"], cases=[], related=["des_nichtigkeit", "des_nichtigkeitsverfahren_dpma"]),
    # ------------------------------------------------------------------ Schutzwirkung und Schranken
    c("des_schutzgegenstand", "Schutzgegenstand (§ 37 DesignG)", W,
      "Der Schutz wird für diejenigen Merkmale der Erscheinungsform begründet, die in der Anmeldung sichtbar wiedergegeben sind (§ 37 Abs. 1 DesignG, ab 2027 Art. 15 DesignRL 2024, Art. 18a GGV). Der Schutzgegenstand ist durch Auslegung der Wiedergabe zu ermitteln, wenn mehrere Darstellungen voneinander abweichen.",
      "Leitlinien der BGH-Rechtsprechung: Mehrere Darstellungen bilden einen Schutzgegenstand, Unklarheiten sind auszulegen, Teile des Designs sind nicht eigenständig geschützt (Weinkaraffe); zeigen die Darstellungen verschiedene Ausführungsformen, für die Schutz beansprucht wird, ist das Design nichtig (Sporthelm, Sportbrille); die Auslegung kann aber zur Schnittmenge der gemeinsamen Merkmale oder zu einem Teil des dargestellten Erzeugnisses führen (Schneidebrett). Nicht abgebildete Seiten, Farben und Materialien sind nicht geschützt; die Beschreibung (§ 10 DesignV) kann die Auslegung stützen, aber nichts hinzufügen.",
      norms=["§ 37 Abs. 1 DesignG", "§ 11 Abs. 6 DesignG", "§ 7 DesignV", "§ 10 DesignV", "Art. 18a GGV", "Art. 15 DesignRL 2024"], cases=["des_bgh_weinkaraffe", "des_bgh_sporthelm", "des_bgh_sportbrille", "des_bgh_schneidebrett", "des_bgh_schreibgeraete"], related=["des_wiedergabe", "des_design_begriff", "des_schutzumfang"]),
    c("des_schutzumfang", "Schutzumfang (§ 38 Abs. 2 DesignG)", W,
      "Der Schutz erstreckt sich auf jedes Design, das beim informierten Benutzer keinen anderen Gesamteindruck erweckt; dabei wird der Grad der Gestaltungsfreiheit des Entwerfers berücksichtigt (§ 38 Abs. 2 DesignG, Art. 9 DesignRL, Art. 10 GGV).",
      "Der Schutzumfang ist das Spiegelbild der Eigenart: Er richtet sich nach dem Abstand des Klagedesigns zum vorbekannten Formenschatz und nach der Musterdichte (BGH Untersetzer, Kinderwagen II). Ein Design mit großem Abstand schützt auch gegen weiter entfernte Gestaltungen; ein Design nahe am Formenschatz nur gegen fast identische. Der Vergleich erfolgt zwischen dem eingetragenen Design (nicht dem vertriebenen Produkt) und dem angegriffenen Erzeugnis in seiner konkreten Form, bei Schwarz-Weiß-Eintragung ohne Farbe (BGH Schreibgeräte). Verwechslungsgefahr, Herkunftstäuschung oder Kenntnis des Verletzers sind nicht erforderlich (objektiver Schutz), außer während der Aufschiebung (§ 38 Abs. 3 DesignG) und beim nicht eingetragenen Unionsgeschmacksmuster (Art. 19 Abs. 4 GGV).",
      norms=["§ 38 Abs. 2 DesignG", "§ 38 Abs. 3 DesignG", "Art. 10 GGV", "Art. 9 DesignRL"], cases=["des_bgh_untersetzer", "des_bgh_kinderwagen_ii", "des_bgh_meda_gate", "des_bgh_ballerinaschuh", "des_bgh_schreibgeraete", "des_eugh_pepsico"], related=["des_eigenart", "des_gesamteindruck", "des_gestaltungsfreiheit", "des_formenschatz", "des_benutzung"]),
    c("des_benutzung", "Benutzungshandlungen und Verletzung (§ 38 Abs. 1 DesignG)", W,
      "Das eingetragene Design gewährt das ausschließliche Recht, es zu benutzen und Dritten die Benutzung ohne Zustimmung zu verbieten; Benutzung ist insbesondere Herstellen, Anbieten, Inverkehrbringen, Ein- und Ausfuhr, Gebrauch eines Erzeugnisses, in das das Design aufgenommen ist, und Besitz zu diesen Zwecken (§ 38 Abs. 1 DesignG, Art. 12 DesignRL, Art. 19 GGV).",
      "Verletzung = Benutzung eines Designs im Schutzumfang (§ 38 Abs. 2 DesignG) ohne Zustimmung und ohne Schranke (§§ 40, 40a, 41, 48 DesignG). Anders als im Markenrecht kommt es weder auf Handeln im geschäftlichen Verkehr an (dafür die Privatgebrauchsschranke § 40 Nr. 1 DesignG) noch auf eine kennzeichenmäßige Benutzung. Auch der Inhaber eines jüngeren eingetragenen Designs kann Verletzer sein (EuGH Celaya). Begehungsgefahr für das Herstellen in der Union besteht schon, wenn außerhalb hergestellt und in der Union vertrieben wird (BGH Kinderwagen I). Ab 2027 auch das Erstellen und Weitergeben von 3D-Druck-Dateien und die Durchfuhr (Art. 16 DesignRL 2024, Art. 19 GGV).",
      norms=["§ 38 Abs. 1 DesignG", "§ 42 DesignG", "Art. 19 GGV", "Art. 12 DesignRL", "Art. 16 DesignRL 2024"], cases=["des_eugh_celaya", "des_bgh_kinderwagen_i"], related=["des_schutzumfang", "des_unterlassung", "des_schranken", "des_erschoepfung"]),
    c("des_vermutung_rechtsgueltigkeit", "Vermutung der Rechtsgültigkeit (§ 39 DesignG)", W,
      "Zugunsten des Rechtsinhabers wird vermutet, dass die Anforderungen an die Rechtsgültigkeit des eingetragenen Designs erfüllt sind (§ 39 DesignG, Art. 85 Abs. 1 GGV, ab 2027 Art. 17 DesignRL 2024).",
      "Konsequenz des ungeprüften Registerrechts: Der Verletzer muss Neuheit und Eigenart durch Widerklage oder DPMA-Antrag angreifen (§ 52a DesignG); im Verfügungsverfahren kann das Gericht die Vermutung bei substantiiertem Vortrag als erschüttert ansehen. Beim nicht eingetragenen Unionsgeschmacksmuster gilt die Vermutung nur, wenn der Inhaber Offenbarung und die Eigenart begründenden Merkmale darlegt (Art. 85 Abs. 2 GGV, EuGH Karen Millen); die Inhaberschaft muss er beweisen (BGH Bolerojäckchen).",
      norms=["§ 39 DesignG", "§ 52a DesignG", "Art. 85 GGV", "Art. 17 DesignRL 2024"], cases=["des_eugh_karen_millen", "des_bgh_bolerojaeckchen", "des_eugh_celaya"], related=["des_widerklage_nichtigkeit", "des_pruefung_dpma", "des_ggm_nicht_eingetragen"]),
    c("des_schranken", "Schranken (§ 40 DesignG)", W,
      "Rechte aus dem Design können nicht geltend gemacht werden gegenüber Handlungen im privaten Bereich zu nichtgewerblichen Zwecken, Handlungen zu Versuchszwecken, Wiedergaben zum Zwecke der Zitierung oder der Lehre (bei Lauterkeit und Quellenangabe) sowie gegenüber Einrichtungen von Schiffen und Luftfahrzeugen im vorübergehenden Inlandsaufenthalt (§ 40 DesignG, Art. 13 DesignRL, Art. 20 GGV).",
      "Weitere Einwendungen: Vorbenutzungsrecht (§ 41 DesignG), Erschöpfung (§ 48 DesignG), Reparaturklausel (§ 40a DesignG), Aufschiebung (§ 38 Abs. 3 DesignG: keine Nachahmung), Verjährung (§ 49 DesignG), Lizenz und Zustimmung. Ab 2027 kommen Referenznutzung sowie Kommentar, Kritik und Parodie hinzu (Art. 18 DesignRL 2024, schon jetzt Art. 20 Abs. 1 lit. d, e GGV). Eine Privilegierung des Ersatzteilhandels als solche gibt es außerhalb der Reparaturklausel nicht.",
      norms=["§ 40 DesignG", "§ 41 DesignG", "§ 48 DesignG", "§ 40a DesignG", "Art. 20 GGV", "Art. 18 DesignRL 2024"], cases=["des_bgh_ice", "des_eugh_nintendo"], related=["des_zitierschranke", "des_reparaturklausel", "des_vorbenutzungsrecht", "des_erschoepfung"]),
    c("des_zitierschranke", "Zitat und Lehre (§ 40 Nr. 3 DesignG)", W,
      "Wiedergaben zum Zwecke der Zitierung oder der Lehre sind frei, wenn sie mit den Gepflogenheiten des redlichen Geschäftsverkehrs vereinbar sind, die normale Verwertung nicht unangemessen beeinträchtigen und die Quelle angeben (§ 40 Nr. 3 DesignG, Art. 20 Abs. 1 lit. c GGV).",
      "Zitieren verlangt eine innere Verbindung zwischen dem wiedergegebenen Design und eigenen Gedanken des Zitierenden: Das Design muss Belegstelle oder Erörterungsgrundlage sein, die bloße dekorative Abbildung (ICE auf einem Kalender) genügt nicht (BGH ICE). Zulässig ist dagegen die Abbildung des Originalprodukts, um die Verwendung eigenen Zubehörs zu erläutern (EuGH Nintendo/BigBen: Kompatibilitätshinweis), sofern Lauterkeit und Quellenangabe gewahrt sind.",
      norms=["§ 40 DesignG", "Art. 20 GGV"], cases=["des_bgh_ice", "des_eugh_nintendo"], related=["des_schranken"]),
    c("des_reparaturklausel", "Reparaturklausel (§ 40a DesignG, Art. 20a GGV)", W,
      "Es besteht kein Designschutz für ein Bauelement eines komplexen Erzeugnisses, das allein mit dem Ziel verwendet wird, die Reparatur dieses Erzeugnisses zu ermöglichen, um ihm wieder sein ursprüngliches Erscheinungsbild zu verleihen, sofern die Verbraucher über den Ursprung des Ersatzteils unterrichtet werden (§ 40a DesignG, seit 2.12.2020; Art. 20a GGV, seit 1.5.2025; Art. 19 DesignRL 2024, zwingend ab 2027).",
      "Betroffen sind formgebundene Ersatzteile („must match“: Kotflügel, Türen, Scheinwerfer), nicht frei gestaltbare Teile wie Felgen oder Lenkräder; Art. 20a GGV und Art. 19 DesignRL 2024 beschränken die Klausel ausdrücklich auf Teile, von deren Erscheinungsform das Design abhängt (§ 40a DesignG nennt dieses Merkmal nicht ausdrücklich). Nach Art. 110 GGV a.F. galt sie auch für formungebundene Teile wie Felgen (EuGH Acacia/Audi und Porsche, BGH Kraftfahrzeugfelgen II, Schlüsselgehäuse), verlangte aber Identität mit dem Original und Sorgfaltspflichten des Anbieters (Hinweise, Vertragsbedingungen, Kontrollen). Bestandsschutz: § 40a DesignG gilt nicht für vor dem 2.12.2020 angemeldete Designs (§ 73 Abs. 2 DesignG); die Richtlinie 2024/2823 erlaubt ihn bis 9.12.2032.",
      norms=["§ 40a DesignG", "§ 73 DesignG", "Art. 20a GGV", "Art. 19 DesignRL 2024", "Art. 14 DesignRL"], cases=["des_eugh_acacia_audi", "des_bgh_kraftfahrzeugfelgen_ii", "des_bgh_schluesselgehaeuse"], related=["des_bauelement_sichtbarkeit", "des_schranken", "des_verbindungselemente"]),
    c("des_vorbenutzungsrecht", "Vorbenutzungsrecht (§ 41 DesignG)", W,
      "Rechte aus dem Design können nicht gegen einen Dritten geltend gemacht werden, der vor dem Anmeldetag im Inland ein identisches, unabhängig entwickeltes Design gutgläubig in Benutzung genommen oder wirkliche und ernsthafte Anstalten dazu getroffen hat; er darf das Design für die Bedürfnisse seines Betriebs weiterbenutzen (§ 41 DesignG, Art. 22 GGV, ab 2027 Art. 21 DesignRL 2024).",
      "Ernsthafte Anstalten sind Vorbereitungshandlungen aller Art, die den ernstlichen Willen zur alsbaldigen Benutzung sicher erkennen lassen; sie müssen im Inland getroffen sein (BGH Bettgestell). Das Recht ist nur mit dem Unternehmensteil übertragbar (§ 41 Abs. 2 DesignG) und erlaubt keine Lizenzvergabe. Praktische Bedeutung: unabhängige Parallelentwicklungen, die die Neuheitsschonfrist des Anmelders nicht sperrt.",
      norms=["§ 41 DesignG", "Art. 22 GGV", "Art. 21 DesignRL 2024"], cases=["des_bgh_bettgestell"], related=["des_schranken", "des_neuheitsschonfrist"]),
    c("des_erschoepfung", "Erschöpfung (§ 48 DesignG)", W,
      "Die Rechte aus dem Design erstrecken sich nicht auf Handlungen, die ein Erzeugnis betreffen, das vom Rechtsinhaber oder mit seiner Zustimmung in einem Mitgliedstaat der EU oder des EWR in Verkehr gebracht wurde (§ 48 DesignG, Art. 15 DesignRL, Art. 21 GGV).",
      "Unionsweite, keine internationale Erschöpfung: Der Import von in den USA verkauften Originalprodukten bleibt verboten (parallel § 24 MarkenG, BGH- und EuGH-Rechtsprechung zum Markenrecht). Erschöpft ist nur das konkrete Stück; Umgestaltung oder Neuherstellung (auch aus Teilen) ist keine erschöpfte Handlung. Anders als § 24 Abs. 2 MarkenG kennt § 48 DesignG keine ausdrückliche Rückausnahme für berechtigte Gründe.",
      norms=["§ 48 DesignG", "Art. 21 GGV", "Art. 15 DesignRL", "Art. 20 DesignRL 2024"], cases=[], related=["des_schranken", "des_benutzung"]),
    # ------------------------------------------------------------------ Rechtsfolgen und Verfahren
    c("des_unterlassung", "Beseitigung und Unterlassung (§ 42 Abs. 1 DesignG)", R,
      "Wer ein eingetragenes Design entgegen § 38 Abs. 1 DesignG benutzt, kann vom Rechtsinhaber oder einem anderen Berechtigten auf Beseitigung und bei Wiederholungsgefahr auf Unterlassung in Anspruch genommen werden; der Unterlassungsanspruch besteht auch bei drohender Erstbegehung (§ 42 Abs. 1 DesignG, Umsetzung von Art. 11 DurchsetzungsRL).",
      "Verschuldensunabhängig; Wiederholungsgefahr wird durch eine begangene Verletzung vermutet und nur durch strafbewehrte Unterlassungserklärung ausgeräumt. Aktivlegitimiert sind Rechtsinhaber und ausschließlicher Lizenznehmer nach § 31 Abs. 3 DesignG. Gleichlautend § 14 Abs. 5 MarkenG, § 139 Abs. 1 PatG, § 97 Abs. 1 UrhG; für Unionsgeschmacksmuster folgt die Unterlassung direkt aus Art. 89 Abs. 1 GGV. Durchsetzung im Eilverfahren nach §§ 935 ff. ZPO ohne Dringlichkeitsvermutung (anders § 12 Abs. 1 UWG, § 140 Abs. 3 MarkenG). Der Verhältnismäßigkeitseinwand des § 139 Abs. 1 S. 3 PatG fehlt im DesignG.",
      norms=["§ 42 Abs. 1 DesignG", "§ 31 Abs. 3 DesignG", "§ 44 DesignG", "Art. 89 GGV", "Art. 11 DurchsetzungsRL"], cases=["des_bgh_kinderwagen_i", "des_bgh_griffleiste"], related=["des_benutzung", "des_schadensersatz", "des_vernichtung_rueckruf", "des_anspruchsgrundlagen_eu"]),
    c("des_schadensersatz", "Schadensersatz und Entschädigung (§ 42 Abs. 2, § 45 DesignG)", R,
      "Bei Vorsatz oder Fahrlässigkeit ist der Verletzer zum Schadensersatz verpflichtet; der Schaden kann konkret, nach dem Verletzergewinn oder nach der angemessenen Lizenzgebühr berechnet werden (§ 42 Abs. 2 DesignG, Art. 13 DurchsetzungsRL). Der schuldlose Verletzer kann Unterlassung und Vernichtung durch eine Geldentschädigung in Höhe der Lizenzgebühr abwenden, wenn ihm sonst ein unverhältnismäßiger Schaden droht (§ 45 DesignG, Art. 12 DurchsetzungsRL).",
      "Fahrlässigkeit wird im gewerblichen Rechtsschutz streng beurteilt: Wer Produkte vertreibt, muss das Register prüfen. Die dreifache Schadensberechnung ist wie in § 14 Abs. 6 MarkenG und § 139 Abs. 2 PatG; zur Bezifferung dient der unselbständige Auskunfts- und Rechnungslegungsanspruch aus § 242 BGB. Die Entschädigungsoption des § 45 DesignG gibt es nur im DesignG und UrhG (§ 100 UrhG), nicht im MarkenG oder PatG. Für Gemeinschaftsgeschmacksmuster gilt § 42 Abs. 2 DesignG über § 62a DesignG und Art. 88 Abs. 2 GGV (EuGH Acacia/BMW).",
      norms=["§ 42 Abs. 2 DesignG", "§ 45 DesignG", "§ 62a DesignG", "Art. 13 DurchsetzungsRL", "Art. 12 DurchsetzungsRL", "Art. 88 GGV"], cases=["des_eugh_acacia_bmw"], related=["des_unterlassung", "des_auskunft", "des_verjaehrung", "des_anspruchsgrundlagen_eu"]),
    c("des_vernichtung_rueckruf", "Vernichtung, Rückruf, Überlassung (§ 43 DesignG)", R,
      "Der Verletzte kann Vernichtung der rechtswidrig hergestellten oder verbreiteten Erzeugnisse und der vorwiegend dazu benutzten Vorrichtungen (§ 43 Abs. 1 DesignG), Rückruf und endgültiges Entfernen aus den Vertriebswegen (§ 43 Abs. 2 DesignG) oder statt der Vernichtung Überlassung gegen Vergütung bis zu den Herstellungskosten (§ 43 Abs. 3 DesignG) verlangen; ausgeschlossen bei Unverhältnismäßigkeit (§ 43 Abs. 4 DesignG). Umsetzung von Art. 10 DurchsetzungsRL.",
      "Parallelnormen: § 18 MarkenG, § 140a PatG, § 24a GebrMG, § 98 UrhG. Der Überlassungsanspruch ist eine Besonderheit von DesignG und UrhG. Gebäudebestandteile und ausscheidbare rechtmäßige Teile sind ausgenommen (§ 43 Abs. 5 DesignG). Der Anspruch richtet sich gegen Verletzer und Unternehmensinhaber (§ 44 DesignG) und ist verschuldensunabhängig.",
      norms=["§ 43 DesignG", "§ 44 DesignG", "Art. 10 DurchsetzungsRL"], cases=[], related=["des_unterlassung", "des_anspruchsgrundlagen_eu"]),
    c("des_auskunft", "Auskunft und Drittauskunft (§ 46 DesignG)", R,
      "Der Verletzer schuldet unverzügliche Auskunft über Herkunft und Vertriebsweg der rechtsverletzenden Erzeugnisse (§ 46 Abs. 1 DesignG); bei offensichtlicher Verletzung oder nach Klageerhebung auch Dritte, die in gewerblichem Ausmaß Erzeugnisse besaßen, Dienstleistungen nutzten oder erbrachten (§ 46 Abs. 2 DesignG). Inhalt: Namen und Anschriften von Herstellern, Lieferanten, gewerblichen Abnehmern und Mengen und Preise (§ 46 Abs. 3 DesignG). Umsetzung von Art. 8 DurchsetzungsRL.",
      "Gleichlautend § 19 MarkenG, § 140b PatG, § 101 UrhG. Bei offensichtlicher Verletzung im Wege der einstweiligen Verfügung (§ 46 Abs. 7 DesignG); Verkehrsdaten nur mit richterlicher Anordnung (§ 46 Abs. 9 DesignG). Daneben der Rechnungslegungsanspruch aus § 242 BGB zur Bezifferung des Schadensersatzes (Umsätze, Gewinn, Kosten), der weiter reicht als § 46 DesignG. Vorlage und Besichtigung (§ 46a DesignG) und Sicherung von Schadensersatzansprüchen (§ 46b DesignG) ergänzen die Beweisbeschaffung.",
      norms=["§ 46 DesignG", "§ 46a DesignG", "§ 46b DesignG", "Art. 8 DurchsetzungsRL", "Art. 6 DurchsetzungsRL"], cases=[], related=["des_schadensersatz", "des_vorlage_besichtigung", "des_anspruchsgrundlagen_eu"]),
    c("des_vorlage_besichtigung", "Vorlage, Besichtigung, Sicherung (§§ 46a, 46b DesignG)", R,
      "Bei hinreichender Wahrscheinlichkeit einer Verletzung kann der Berechtigte Vorlage einer Urkunde oder Besichtigung einer Sache verlangen, auch durch einstweilige Verfügung mit Geheimnisschutz (§ 46a DesignG, Art. 6, 7 DurchsetzungsRL); bei Verletzung in gewerblichem Ausmaß und gefährdeter Erfüllung des Schadensersatzanspruchs auch Vorlage von Bank-, Finanz- und Handelsunterlagen (§ 46b DesignG, Art. 9 Abs. 2 DurchsetzungsRL).",
      "Parallelnormen § 19a, 19b MarkenG, § 140c, 140d PatG. Bei Designs ist die Besichtigung selten nötig, weil die Verletzung an der Produktoberfläche sichtbar ist; Bedeutung hat § 46a DesignG bei Vorserienmodellen und Messeexponaten. Wer unberechtigt Vorlage verlangt, haftet auf Schadensersatz (§ 46a Abs. 5 DesignG).",
      norms=["§ 46a DesignG", "§ 46b DesignG", "Art. 6 DurchsetzungsRL", "Art. 7 DurchsetzungsRL", "Art. 9 DurchsetzungsRL"], cases=[], related=["des_auskunft", "des_anspruchsgrundlagen_eu"]),
    c("des_verjaehrung", "Verjährung und Urteilsbekanntmachung (§§ 47, 49 DesignG)", R,
      "Die Ansprüche aus §§ 42 bis 47 DesignG verjähren nach §§ 194 ff. BGB (drei Jahre ab Kenntnis, zehn Jahre absolut); danach bleibt der Restschadensersatz nach § 852 BGB (§ 49 DesignG). Die obsiegende Partei kann bei berechtigtem Interesse die Befugnis zur Urteilsbekanntmachung erhalten; sie erlischt drei Monate nach Rechtskraft (§ 47 DesignG, Art. 15 DurchsetzungsRL).",
      "Parallel § 20 MarkenG, § 141 PatG, § 102 UrhG. Dauerhandlungen werden für die Verjährung in Einzelakte zerlegt (BGH Motorradteile zum UrhG). Beim Gemeinschaftsgeschmacksmuster richten sich Verjährung und Verwirkung nach nationalem Recht (EuGH Gautzsch/Duna, § 62a DesignG).",
      norms=["§ 49 DesignG", "§ 47 DesignG", "§ 62a DesignG", "Art. 15 DurchsetzungsRL"], cases=["des_eugh_gautzsch"], related=["des_schadensersatz", "des_anspruchsgrundlagen_eu"]),
    c("des_designstreitsachen", "Designstreitsachen und Gerichtsstand (§§ 52 bis 54 DesignG)", R,
      "Für Designstreitsachen sind die Landgerichte ohne Rücksicht auf den Streitwert ausschließlich zuständig (§ 52 Abs. 1 DesignG), mit Konzentration bei bestimmten Designgerichten (§ 52 Abs. 2 DesignG); Patentanwaltskosten sind nach § 13 RVG zu erstatten (§ 52 Abs. 4 DesignG). Ansprüche, die auch auf das UWG gestützt werden, können beim Designgericht geltend gemacht werden (§ 53 DesignG); Streitwertbegünstigung nach § 54 DesignG.",
      "Nichtigkeit gehört nicht zur Designstreitsache (DPMA oder Widerklage). Für Unionsgeschmacksmuster sind die Landgerichte Unionsgeschmacksmustergerichte (§ 63 DesignG, Art. 80 GGV) mit unionsweiter Zuständigkeit im Sitzgerichtsstand (Art. 82, 83 GGV). Wer im Inland keinen Sitz hat, braucht einen Inlandsvertreter (§ 58 DesignG). Ein durch Insolvenz unterbrochener Unterlassungsprozess kann auch bei Eigenverwaltung aufgenommen werden (BGH Griffleiste).",
      norms=["§ 52 DesignG", "§ 53 DesignG", "§ 54 DesignG", "§ 58 DesignG", "§ 63 DesignG", "Art. 80 GGV"], cases=["des_bgh_griffleiste"], related=["des_widerklage_nichtigkeit", "des_ggm_gericht", "des_zollbeschlagnahme"]),
    c("des_zollbeschlagnahme", "Grenzbeschlagnahme und Strafbarkeit (§§ 51, 55 bis 57a DesignG)", R,
      "Bei offensichtlicher Verletzung unterliegen Erzeugnisse auf Antrag und gegen Sicherheitsleistung bei Ein- und Ausfuhr der Beschlagnahme durch die Zollbehörde, soweit nicht die Verordnung (EU) Nr. 608/2013 gilt (§ 55 DesignG); Verfahren, Widerspruch und Einziehung regeln §§ 56, 57 DesignG. Die vorsätzliche Designverletzung ist strafbar (§ 51 DesignG, gewerbsmäßig bis fünf Jahre), ebenso die Verletzung eines Unionsgeschmacksmusters (§ 65 DesignG).",
      "Praktisch läuft die Grenzbeschlagnahme über den unionsrechtlichen Antrag nach der VO (EU) Nr. 608/2013 bei der Generalzolldirektion; § 55 DesignG erfasst den innerdeutschen und EWR-Verkehr. Parallelnormen §§ 146 ff. MarkenG, §§ 142a, 142b PatG; Art. 16 DurchsetzungsRL überlässt Strafrecht und Grenzbeschlagnahme den Mitgliedstaaten.",
      norms=["§ 55 DesignG", "§ 56 DesignG", "§ 57 DesignG", "§ 51 DesignG", "§ 65 DesignG", "Art. 16 DurchsetzungsRL"], cases=[], related=["des_designstreitsachen", "des_anspruchsgrundlagen_eu"]),
    # ------------------------------------------------------------------ Unionsgeschmacksmuster und internationales Design
    c("des_ggm_eingetragen", "Eingetragenes Unionsgeschmacksmuster (Art. 1, 12, 19 GGV)", U,
      "Das eingetragene Unionsgeschmacksmuster (bis 30.4.2025: Gemeinschaftsgeschmacksmuster) entsteht durch Eintragung beim EUIPO, gilt einheitlich in der gesamten Union (Art. 1 Abs. 3 GGV), dauert fünf Jahre und ist bis 25 Jahre ab Anmeldetag verlängerbar (Art. 12 GGV); es gewährt ein objektives Verbotsrecht wie § 38 DesignG (Art. 19 Abs. 1 GGV).",
      "Schutzvoraussetzungen, Ausschlüsse, Schutzumfang und Schranken sind wortgleich mit dem DesignG (Art. 4 bis 10, 20 bis 22 GGV). Anmeldung nur noch beim EUIPO (Art. 35 Abs. 1 GGV; die Weiterleitung über das DPMA nach § 62 DesignG ist seit 1.5.2025 entfallen), Sammelanmeldung bis 50 Muster, Aufschiebung 30 Monate, Nichtigkeit durch das EUIPO (Art. 52 GGV) oder Widerklage (Art. 84 GGV). Verletzungsklagen vor den Unionsgeschmacksmustergerichten (Art. 80 ff. GGV, § 63 DesignG). Die Reform 2024 (Verordnung (EU) 2024/2822) brachte den neuen Namen, die Reparaturklausel (Art. 20a GGV), 3D-Druck und Durchfuhr (Art. 19 Abs. 2 lit. d, Abs. 3 GGV), das Symbol Ⓓ und flexiblere Darstellungen. Internationale Eintragung mit Benennung der EU nach dem Haager Abkommen (Art. 106a ff. GGV).",
      norms=["Art. 1 GGV", "Art. 12 GGV", "Art. 19 GGV", "Art. 35 GGV", "Art. 37 GGV", "Art. 52 GGV", "§ 62 DesignG", "§ 63 DesignG"], cases=["des_eugh_celaya", "des_bgh_weinkaraffe", "des_bgh_untersetzer"], related=["des_ggm_nicht_eingetragen", "des_ggm_gericht", "des_ggm_anwendbares_recht", "des_unionsreform_2024"]),
    c("des_ggm_nicht_eingetragen", "Nicht eingetragenes Unionsgeschmacksmuster (Art. 11, 19 Abs. 4 GGV)", U,
      "Ein Design, das die Schutzvoraussetzungen erfüllt, ist ohne Eintragung für drei Jahre ab dem Tag geschützt, an dem es erstmals innerhalb der Union der Öffentlichkeit zugänglich gemacht wurde (Art. 11 GGV); der Schutz richtet sich nur gegen Nachahmungen, nicht gegen unabhängige Parallelschöpfungen (Art. 19 Abs. 4 GGV).",
      "Das Recht der Modebranche: Schutz ohne Formalitäten, aber kurz und schwächer. Der Inhaber muss Offenbarung in der Union (nicht nur weltweit: EuGH Gautzsch), Zeitpunkt, Inhaberschaft (BGH Bolerojäckchen) und Nachahmung beweisen; die Eigenart muss er nur angeben (Art. 85 Abs. 2 GGV, EuGH Karen Millen). Auch Teile eines offenbarten Gesamterzeugnisses können geschützt sein, wenn sie erkennbar abgegrenzt sind (EuGH Ferrari/Mansory, BGH Front kit II). Die Offenbarung startet zugleich die zwölfmonatige Neuheitsschonfrist für eine spätere Eintragung. Ein nationales nicht eingetragenes Design gibt es nicht; Ersatz ist § 4 Nr. 3 UWG (BGH Jeans: kumulativ anwendbar).",
      norms=["Art. 11 GGV", "Art. 19 GGV", "Art. 7 GGV", "Art. 85 GGV", "Art. 14 GGV"], cases=["des_eugh_gautzsch", "des_eugh_karen_millen", "des_bgh_bolerojaeckchen", "des_eugh_ferrari", "des_bgh_front_kit_ii", "des_bgh_jeans"], related=["des_ggm_eingetragen", "des_offenbarung", "des_neuheitsschonfrist", "des_uwg_nachahmung"]),
    c("des_ggm_gericht", "Unionsgeschmacksmustergerichte und Zuständigkeit (Art. 80 bis 83 GGV, § 63 DesignG)", U,
      "Verletzungsklagen und Nichtigkeitswiderklagen gehören ausschließlich vor die von den Mitgliedstaaten benannten Unionsgeschmacksmustergerichte (Art. 80, 81 GGV; in Deutschland die Landgerichte, § 63 DesignG). International zuständig ist das Gericht am Sitz des Beklagten, hilfsweise des Klägers, hilfsweise Spanien, alternativ das Gericht des Verletzungsorts (Art. 82 GGV); nur der Sitzgerichtsstand reicht unionsweit (Art. 83 GGV).",
      "Im Gerichtsstand der Streitgenossenschaft (Art. 8 Nr. 1 Brüssel-Ia-VO) kann ein Gericht unionsweite Verbote auch gegen den ausländischen Mitbeklagten aussprechen (EuGH Nintendo/BigBen). Aussetzung wegen eines EUIPO-Nichtigkeitsantrags nach Art. 91 GGV nur, wenn der Antrag vor der Klage gestellt wurde (BGH Kinderwagen I). Örtliche Zuständigkeit nach § 63b DesignG.",
      norms=["Art. 80 GGV", "Art. 81 GGV", "Art. 82 GGV", "Art. 83 GGV", "Art. 91 GGV", "§ 63 DesignG"], cases=["des_eugh_nintendo", "des_bgh_kinderwagen_i"], related=["des_ggm_eingetragen", "des_ggm_anwendbares_recht", "des_designstreitsachen"]),
    c("des_ggm_anwendbares_recht", "Anwendbares Recht und Sanktionen (Art. 88, 89 GGV, § 62a DesignG)", U,
      "Das Unionsgeschmacksmustergericht wendet die Verordnung an und ergänzend sein nationales Recht einschließlich des IPR (Art. 88 GGV). Die Unterlassung folgt aus Art. 89 Abs. 1 GGV; weitere Maßnahmen (etwa Beschlagnahme, Vernichtung) richten sich nach Art. 89 Abs. 2 GGV nach dem anwendbaren Recht (bis 30.4.2025 Art. 89 Abs. 1 lit. b bis d GGV a.F.: Recht des Mitgliedstaats, in dem die Verletzung begangen wurde).",
      "Für Folgeansprüche (Schadensersatz, Auskunft, Rückruf, Kosten) gilt nach Art. 88 Abs. 2 GGV i.V.m. Art. 8 Abs. 2 Rom-II-VO das Recht des Staates der Verletzungshandlung (EuGH Acacia/BMW, Nintendo/BigBen); für Deutschland ordnet § 62a DesignG die entsprechende Anwendung der §§ 42 bis 47, 49 DesignG an (aus § 42 Abs. 1 DesignG nur die Beseitigung, weil die Unterlassung aus Art. 89 Abs. 1 GGV folgt). Deshalb steht in der Anspruchsgrundlagentabelle für Unionsgeschmacksmuster stets ein Doppelzitat: Art. 89 GGV plus die nationale Norm.",
      norms=["Art. 88 GGV", "Art. 89 GGV", "Art. 90 GGV", "§ 62a DesignG"], cases=["des_eugh_acacia_bmw", "des_eugh_nintendo", "des_eugh_gautzsch"], related=["des_ggm_gericht", "des_anspruchsgrundlagen_eu", "des_schadensersatz"]),
    c("des_haager_abkommen", "Internationale Eintragung nach dem Haager Abkommen (§§ 66 bis 71 DesignG)", U,
      "Nach der Genfer Akte des Haager Abkommens kann ein Design mit einer Anmeldung beim Internationalen Büro der WIPO (direkt oder über das DPMA, § 67 DesignG) für viele Vertragsparteien eingetragen werden; eine Eintragung mit Benennung Deutschlands wirkt wie ein eingetragenes Design ab dem Tag der internationalen Eintragung (§ 71 DesignG), sofern das DPMA nicht binnen sechs Monaten den Schutz verweigert (§ 69 DesignG).",
      "Das DPMA prüft nur die Eintragungshindernisse des § 18 DesignG; Neuheit und Eigenart bleiben dem nationalen Nichtigkeitsverfahren vorbehalten (nachträgliche Schutzentziehung, § 70 DesignG). Die EU ist selbst Vertragspartei: Benennung „EM“ ergibt ein Unionsgeschmacksmuster (Art. 106a ff. GGV). Für Designs gibt es keine Entsprechung zur Unionsmarken-Umwandlung.",
      norms=["§ 66 DesignG", "§ 67 DesignG", "§ 69 DesignG", "§ 70 DesignG", "§ 71 DesignG", "Art. 106a GGV", "§ 23 DesignV"], cases=[], related=["des_ggm_eingetragen", "des_anmeldung"]),
    # ------------------------------------------------------------------ Europäischer Rahmen und Abgrenzung
    c("des_designrl", "Richtlinie 98/71/EG (DesignRL)", E,
      "Die Richtlinie 98/71/EG harmonisiert das materielle Recht der eingetragenen Muster in den Mitgliedstaaten: Begriffe, Schutzvoraussetzungen, Ausschlüsse, Schutzumfang, Schutzdauer, Nichtigkeitsgründe, Rechte, Schranken und Erschöpfung (Art. 1 bis 17 DesignRL). Deutschland hat sie mit dem Geschmacksmusterreformgesetz vom 12.3.2004 (in Kraft 1.6.2004) umgesetzt; das DesignG folgt ihr fast wörtlich.",
      "Nicht harmonisiert sind Verfahren, Sanktionen und Rechtsfolgen (Erwägungsgründe 5 und 6), dafür gilt die Durchsetzungsrichtlinie 2004/48/EG (§§ 42 bis 47 DesignG). Die Reparaturklausel blieb offen (Art. 14 DesignRL, „freeze plus“). Die Richtlinie wird mit Wirkung vom 9.12.2027 durch die Richtlinie (EU) 2024/2823 ersetzt. Auslegungsmaßstab für das DesignG ist die richtlinienkonforme Auslegung; Vorlagen des BGH: Sattelunterseite (Art. 3 Abs. 3, 4 DesignRL, EuGH Monz).",
      norms=["Art. 1 DesignRL", "Art. 3 DesignRL", "Art. 5 DesignRL", "Art. 9 DesignRL", "Art. 11 DesignRL", "Art. 14 DesignRL", "Art. 19 DesignRL"], cases=["des_eugh_monz", "des_bgh_sattelunterseite_ii"], related=["des_designrl_2024", "des_unionsreform_2024", "des_anspruchsgrundlagen_eu"]),
    c("des_designrl_2024", "Richtlinie (EU) 2024/2823 (DesignRL 2024)", E,
      "Die Neufassung der Designrichtlinie vom 23.10.2024 (in Kraft seit 8.12.2024, Umsetzungsfrist 9.12.2027) modernisiert Begriffe (Bewegung, Animation, nicht körperliche Erzeugnisse), harmonisiert Schutzgegenstand, Vermutung der Rechtsgültigkeit und Vorbenutzungsrecht, erweitert die Benutzungshandlungen um 3D-Druck-Dateien und Durchfuhr, ergänzt die Schranken um Referenznutzung, Kritik und Parodie und macht die Reparaturklausel zwingend (Art. 19 DesignRL 2024).",
      "Für Deutschland ändert sich wenig am Ergebnis, weil §§ 37, 39, 40a, 41 DesignG die meisten Neuerungen schon enthalten; anzupassen sind § 1 DesignG (Begriffe), § 38 DesignG (3D-Druck, Durchfuhr), § 40 DesignG (neue Schranken), § 73 Abs. 2 DesignG (Bestandsschutz bis 2032) und die DesignV (digitale Darstellungen, Disclaimer). Bis zur Umsetzung gilt das DesignG unverändert; in Klausuren ist die Rechtslage nach geltendem Recht darzustellen, die Reform als Ausblick.",
      norms=["Art. 2 DesignRL 2024", "Art. 16 DesignRL 2024", "Art. 18 DesignRL 2024", "Art. 19 DesignRL 2024", "Art. 26 DesignRL 2024", "Art. 36 DesignRL 2024"], cases=[], related=["des_designrl", "des_unionsreform_2024", "des_reparaturklausel"]),
    c("des_unionsreform_2024", "Reform des Unionsgeschmacksmusters 2024 (Verordnung (EU) 2024/2822)", E,
      "Die Verordnung (EU) 2024/2822 ändert die GGV mit Wirkung ab 1.5.2025 (Teile ab 1.7.2026): neuer Name Unionsgeschmacksmuster, Amt EUIPO, modernisierte Begriffe, Schutzgegenstand (Art. 18a GGV), 3D-Druck und Durchfuhr (Art. 19 GGV), neue Schranken (Art. 20 GGV), dauerhafte Reparaturklausel (Art. 20a GGV statt Art. 110 GGV a.F.), Sammelanmeldung ohne Klassenbindung (Art. 37 GGV), Eintragungssymbol Ⓓ (Art. 26a GGV), neue Gebührenstruktur.",
      "Die Reform gilt unmittelbar, während die parallele Richtlinie 2024/2823 erst bis Ende 2027 in nationales Recht umgesetzt werden muss: Bis dahin weichen Unionsgeschmacksmuster und deutsches Design in Details voneinander ab (etwa Schranken für Parodie, Referenznutzung). Übergangsrecht für die Reparaturklausel: alte Rechtslage (Art. 110 GGV a.F.) für Handlungen vor dem 1.5.2025 (BGH Schlüsselgehäuse).",
      norms=["Art. 1 GGV", "Art. 18a GGV", "Art. 19 GGV", "Art. 20 GGV", "Art. 20a GGV", "Art. 26a GGV", "Art. 37 GGV"], cases=["des_bgh_schluesselgehaeuse"], related=["des_ggm_eingetragen", "des_designrl_2024", "des_reparaturklausel"]),
    c("des_urheberrecht_kumulation", "Kumulation mit dem Urheberrecht (§ 50 DesignG, Art. 17 DesignRL)", E,
      "Design- und Urheberrechtsschutz können nebeneinander bestehen (§ 50 DesignG, Art. 17 DesignRL, Art. 96 Abs. 2 GGV). Ein Produktdesign ist urheberrechtlich als Werk der angewandten Kunst geschützt, wenn es eine eigene geistige Schöpfung ist, in der sich freie kreative Entscheidungen des Urhebers widerspiegeln; eine besondere ästhetische Wirkung oder ein Überragen der Durchschnittsgestaltung ist nicht erforderlich (EuGH Cofemel, Mio/konektra; BGH Geburtstagszug).",
      "Seit Geburtstagszug (2013) hat der BGH die Stufentheorie aufgegeben: Das Designrecht ist kein Minus zum Urheberrecht mehr, deshalb gelten für angewandte Kunst keine strengeren Anforderungen. Technisch bedingte Merkmale scheiden aus (BGH Seilzirkus), aber technische Erfordernisse schließen den Schutz nicht aus, wenn Raum für freie Gestaltung blieb (EuGH Brompton). Unterschiede: Urheberrecht entsteht formlos, dauert 70 Jahre p.m.a., schützt nur gegen Übernahme der originalen Elemente (nicht nach dem Gesamteindruck) und setzt beim Verletzer Kenntnis des Werks voraus; das Design schützt objektiv, aber nur 25 Jahre und nur eingetragen.",
      norms=["§ 50 DesignG", "Art. 17 DesignRL", "Art. 23 DesignRL 2024", "Art. 96 GGV"], cases=["des_bgh_geburtstagszug", "des_bgh_seilzirkus", "des_eugh_cofemel", "des_eugh_brompton", "des_eugh_mio_konektra"], related=["des_abgrenzung_schutzrechte", "des_uwg_nachahmung", "des_technisch_bedingt"]),
    c("des_uwg_nachahmung", "Ergänzender wettbewerbsrechtlicher Leistungsschutz (§ 4 Nr. 3 UWG)", E,
      "Neben dem Designschutz bleibt der lauterkeitsrechtliche Nachahmungsschutz anwendbar (§ 50 DesignG, Art. 16 DesignRL): Das Anbieten einer Nachahmung ist unlauter, wenn das Erzeugnis wettbewerbliche Eigenart hat und besondere Umstände hinzutreten (vermeidbare Herkunftstäuschung, Rufausbeutung oder unredliche Erlangung der Kenntnisse, § 4 Nr. 3 UWG).",
      "Wettbewerbliche Eigenart ist die Eignung, auf die betriebliche Herkunft oder Besonderheiten hinzuweisen (BGH LIKEaBIKE); für Herkunftstäuschung braucht das Original eine gewisse Bekanntheit (BGH Jeans, Handtuchklemmen), geschützt ist die konkrete Gestaltung, nicht das Konzept (BGH Glück). Das UWG schützt auch ohne Eintragung und ohne Frist, aber nur gegen unlautere Übernahme und nur den Mitbewerber; Ansprüche nach § 4 Nr. 3 UWG und aus dem nicht eingetragenen Unionsgeschmacksmuster schließen sich nicht aus (BGH Jeans). Gerichtsstand: § 53 DesignG.",
      norms=["§ 50 DesignG", "§ 53 DesignG", "Art. 16 DesignRL", "Art. 96 GGV"], cases=["des_bgh_likeabike", "des_bgh_jeans", "des_bgh_glueck", "des_bgh_baugruppe"], related=["des_abgrenzung_schutzrechte", "des_ggm_nicht_eingetragen", "des_urheberrecht_kumulation"]),
    c("des_abgrenzung_schutzrechte", "Design, Marke, Patent, Gebrauchsmuster: Abgrenzung und Kumulation", E,
      "Ein Produkt kann zugleich als Design (Erscheinungsform), als dreidimensionale Marke (Herkunftshinweis, § 3 MarkenG), als Werk der angewandten Kunst (§ 2 UrhG), durch Patent oder Gebrauchsmuster (technische Lehre) und nach § 4 Nr. 3 UWG geschützt sein; die Schutzrechte haben verschiedene Voraussetzungen, Schutzgegenstände, Laufzeiten und Schutzumfänge (§ 50 DesignG).",
      "Abgrenzungslinien: Das Design schützt die Ästhetik ohne Herkunftsfunktion, die Formmarke nur bei Unterscheidungskraft und ohne technisch oder wertbedingte Form (§ 3 Abs. 2 MarkenG); das Patent schützt die technische Lehre, das Design nur, was nicht ausschließlich technisch bedingt ist (ein Patent schließt Designschutz nicht aus: BGH Papierspender). Laufzeiten: Design 25 Jahre, Patent 20, Gebrauchsmuster 10, Marke unbegrenzt, Urheberrecht 70 Jahre p.m.a. Vor Gericht: Designstreitsache vor dem Landgericht, Nichtigkeit beim DPMA, Unionsgeschmacksmuster vor dem Unionsgeschmacksmustergericht.",
      norms=["§ 50 DesignG", "§ 3 Abs. 1 DesignG", "Art. 96 GGV", "Art. 16 DesignRL"], cases=["des_bgh_papierspender", "des_bgh_geburtstagszug", "des_eugh_mio_konektra"], related=["des_urheberrecht_kumulation", "des_uwg_nachahmung", "des_technisch_bedingt"]),
    c("des_anspruchsgrundlagen_eu", "Anspruchsgrundlagen im Unionsrecht und in den deutschen Schutzgesetzen", E,
      "Die zivilrechtlichen Ansprüche bei Verletzung eines Designs, einer Marke, eines Patents, eines Gebrauchsmusters oder eines Urheberrechts folgen demselben Muster, weil sie alle die Durchsetzungsrichtlinie 2004/48/EG umsetzen: Unterlassung und Schadensersatz (Art. 11, 13 DurchsetzungsRL), Vernichtung und Rückruf (Art. 10 DurchsetzungsRL), Auskunft (Art. 8 DurchsetzungsRL), Vorlage und Besichtigung (Art. 6, 7 DurchsetzungsRL), Sicherung (Art. 9 DurchsetzungsRL), Urteilsbekanntmachung (Art. 15 DurchsetzungsRL). Im DesignG stehen sie in §§ 42 bis 47 DesignG, im MarkenG in §§ 14 bis 19c MarkenG, im PatG in §§ 139 bis 140e PatG, im GebrMG in §§ 24 bis 24e GebrMG, im UrhG in §§ 97 bis 103 UrhG.",
      "Für die Unionsschutzrechte gilt ein Doppelzitat: Die Verordnung regelt Verbotsrecht und Unterlassung (Art. 19, 89 GGV; Art. 9, 130 UMV), die Folgeansprüche richten sich nach dem nationalen Recht des Verletzungsstaats (Art. 88 Abs. 2, 89 Abs. 2 GGV; Art. 129, 130 Abs. 2 UMV), in Deutschland über § 62a DesignG bzw. § 119 Nr. 2 MarkenG. Für europäische Patente vor dem EPG gelten Art. 63 bis 68 EPGÜ direkt. Die Tabelle „Anspruchsgrundlagen nach der Durchsetzungsrichtlinie“ stellt die Normen nebeneinander; in der Klausur ist immer die Norm des einschlägigen Gesetzes zu zitieren, nicht die Richtlinie.",
      norms=["§ 42 DesignG", "§ 43 DesignG", "§ 46 DesignG", "§ 62a DesignG", "Art. 89 GGV", "Art. 88 GGV", "Art. 11 DurchsetzungsRL", "Art. 13 DurchsetzungsRL", "Art. 10 DurchsetzungsRL", "Art. 8 DurchsetzungsRL"], cases=["des_eugh_acacia_bmw"], related=["des_unterlassung", "des_schadensersatz", "des_vernichtung_rueckruf", "des_auskunft", "des_ggm_anwendbares_recht", "des_designrl"]),
]
